def _roll(src, w, want_max):
    """Extreme of the w bars BEFORE each bar (never includes the bar itself)."""
    n = len(src)
    out = [None] * n
    if w < 1:
        return out
    for j in range(w, n):
        seg = src[j - w:j]
        out[j] = max(seg) if want_max else min(seg)
    return out


def family_init(ctx):
    b = ctx.bars
    n = len(b)
    h = [float(x["h"]) for x in b]
    l = [float(x["l"]) for x in b]
    c = [float(x["c"]) for x in b]
    dn = int(ctx.p.dc_n)
    fn = int(ctx.p.fail_n)
    xn = int(ctx.p.exit_n)
    an = int(ctx.p.n_period)
    mw = int(ctx.p.max_walk)

    # N = Wilder-smoothed true range, exactly the Turtle definition
    N = [None] * n
    acc = 0.0
    prev = None
    for j in range(n):
        if j == 0:
            tr = h[0] - l[0]
        else:
            pc = c[j - 1]
            tr = max(h[j] - l[j], abs(h[j] - pc), abs(l[j] - pc))
        if j < an:
            acc += tr
            if j == an - 1:
                prev = acc / an
                N[j] = prev
        else:
            prev = ((an - 1) * prev + tr) / an
            N[j] = prev

    hid = _roll(h, dn, True)
    lod = _roll(l, dn, False)
    hif = _roll(h, fn, True)
    lof = _roll(l, fn, False)
    hix = _roll(h, xn, True)
    lox = _roll(l, xn, False)

    # a breakout EVENT is the rising edge: the first bar to clear the channel,
    # not every bar that happens to stay above it
    evdir = [0] * n
    for j in range(n):
        d = 0
        if hid[j] is not None and h[j] > hid[j]:
            d = 1
        elif lod[j] is not None and l[j] < lod[j]:
            d = -1
        if d and j > 0 and evdir[j - 1] == d:
            d = 0
        evdir[j] = d

    # phantom-trade every event, traded or not, to learn whether it WOULD have
    # been a winner: stop first, then the 10-bar trailing exit
    by_resolve = {}
    for j in range(n):
        d = evdir[j]
        if not d:
            continue
        nb = N[j]
        lvl = hid[j] if d > 0 else lod[j]
        if nb is None or nb <= 0 or lvl is None:
            continue
        stop = lvl - 2.0 * nb * d
        end = min(n, j + 1 + mw)
        res = None
        ru = None
        for u in range(j + 1, end):
            if d > 0:
                if l[u] <= stop:
                    res, ru = 0, u
                    break
                if lox[u] is not None and l[u] < lox[u]:
                    res, ru = 1, u
                    break
            else:
                if h[u] >= stop:
                    res, ru = 0, u
                    break
                if hix[u] is not None and h[u] > hix[u]:
                    res, ru = 1, u
                    break
        if res is not None:
            by_resolve.setdefault(ru, []).append((j, res))

    # state at bar i = outcome of the most recent event that has RESOLVED by i
    state = [None] * n
    best_j = -1
    best_r = None
    for i in range(n):
        for (j, r) in by_resolve.get(i, ()):
            if j > best_j:
                best_j, best_r = j, r
        state[i] = best_r

    take = [1] * n
    fail = [0] * n
    for i in range(n):
        d = evdir[i]
        if d:
            if d > 0:
                fail[i] = 1 if (hif[i] is not None and h[i] > hif[i]) else 0
            else:
                fail[i] = 1 if (lof[i] is not None and l[i] < lof[i]) else 0
        # take it only when the last resolved breakout LOST, or there is none
        take[i] = 1 if (state[i] is None or state[i] == 0) else 0

    ctx.ev = ctx.series(evdir, "breakout_event")
    ctx.take = ctx.series(take, "prev_breakout_lost")
    ctx.fail = ctx.series(fail, "failsafe_55")
    ctx.hix = ctx.series(hix, "exit_high")
    ctx.lox = ctx.series(lox, "exit_low")


def signal(ctx, i):
    d = ctx.ev[i]
    if not d:
        return 0
    if int(ctx.p.use_filter) and not ctx.take[i] and not ctx.fail[i]:
        return 0
    return 1 if d > 0 else -1


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    if ctx.positions[0]["side"] == "long":
        v = ctx.lox[i]
        return v is not None and ctx.l[i] < v
    v = ctx.hix[i]
    return v is not None and ctx.h[i] > v
